/* @autogenerated */
import { Component, inject } from '@angular/core';
import { ApiKeyClient } from 'app/features/access/api-key-client/model/api-key-client.model';
import { ApiKeyClientRepository } from 'app/features/access/api-key-client/repository/api-key-client-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'api-key-client-view-enable-action', standalone: false, template: '' })
export class ApiKeyClientViewEnableActionComponent extends ConfirmAction<ApiKeyClient> {
  readonly name = 'enable';
  protected readonly scope = 'access/api-key-client';
  protected readonly repository = inject(ApiKeyClientRepository);

  protected override appliesTo(items: ApiKeyClient[]) {
    return items.every((item) => !item.enabled);
  }

  protected execute([item]: ApiKeyClient[]) {
    return this.repository.enable(item.uid);
  }
}
